<?php
namespace App\Models\Courses;
use App\Enums\Courses\AcademicDocumentStatus;use App\Enums\Courses\AcademicDocumentType;use App\Enums\Courses\DeliveryStatus;use App\Models\Document;use App\Models\User;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class CourseAcademicDocument extends CourseModel{protected $fillable=['course_enrollment_id','course_certificate_template_id','document_id','type','status','code','issue_date','filename','qr_token_hash','qr_token_revoked_at','qr_token_last_used_at','replaced_by_id','annulled_at','annulled_by','annul_reason','last_sent_at','delivery_status','delivery_discard_reason'];protected function casts():array{return ['type'=>AcademicDocumentType::class,'status'=>AcademicDocumentStatus::class,'issue_date'=>'date','qr_token_revoked_at'=>'datetime','qr_token_last_used_at'=>'datetime','annulled_at'=>'datetime','last_sent_at'=>'datetime','delivery_status'=>DeliveryStatus::class];}public function enrollment():BelongsTo{return $this->belongsTo(CourseEnrollment::class,'course_enrollment_id');}public function template():BelongsTo{return $this->belongsTo(CourseCertificateTemplate::class,'course_certificate_template_id');}public function document():BelongsTo{return $this->belongsTo(Document::class);}public function replacement():BelongsTo{return $this->belongsTo(self::class,'replaced_by_id');}public function annulledBy():BelongsTo{return $this->belongsTo(User::class,'annulled_by');}}
